$(".swipe").on("touchstart",function(o){var e=o.originalEvent.touches[0].pageX;$(this).one("touchmove",function(o){var t=o.originalEvent.touches[0].pageX;5<Math.floor(e-t)?$(this).carousel("next"):Math.floor(e-t)<-5&&$(this).carousel("prev")}),$(".swipe").on("touchend",function(){$(this).off("touchmove")})});